public class Solution {
    public ListNode FindStartingPoint(ListNode head) {

        // Raj Thomas 13th May 2026 2:21AM IST
        ListNode fast = head, slow = head;
        bool hasCycle = false;
        while(slow?.next != null && fast?.next?.next != null) {

            slow = slow.next;
            fast = fast.next.next;

            if(slow == fast) {
                hasCycle = true;
                break;
            }
        }

        if(!hasCycle) return null;

        fast = head;
        while(slow != fast) {
            slow = slow.next;
            fast = fast.next;
        }

        return slow;
    }
}
```

